      RustLib.instance.api.crateApiOspOspAppSentReplies(that: this);

  /// Answers whether to use the list, or changes the answer. Off, all it
  /// hid comes back; on, the node fetches it soon.
  Future<HideListState> setHideList({required bool inUse}) => RustLib
      .instance
      .api
      .crateApiOspOspAppSetHideList(that: this, inUse: inUse);

  /// Publishes the owner's profile. `photo`, a file on this phone shrunk
  /// to about 1,024 px, becomes the new picture; without one,
  /// `remove_picture` takes the picture off, or else it stays. The picture
  /// is public, as the name is.
  Future<Profile> setProfile({
    required String name,
    String? summary,
    required List<ProfileLinkEntry> links,
    String? photo,
    required bool removePicture,
  }) => RustLib.instance.api.crateApiOspOspAppSetProfile(
    that: this,
    name: name,
    summary: summary,
    links: links,
    photo: photo,
    removePicture: removePicture,
  );

  /// Lets someone reply to the owner's posts from now on (`allow`), blocks
  /// them (`block`), or with `None` forgets either.
  Future<void> setReplier({required String identity, String? choice}) =>
      RustLib.instance.api.crateApiOspOspAppSetReplier(
        that: this,
        identity: identity,
        choice: choice,
      );

  /// Sets who may reply to one of the owner's posts: `off`, `circle` or
  /// `network`.
  Future<void> setReplyPolicy({
    required String postId,
    required String policy,
  }) => RustLib.instance.api.crateApiOspOspAppSetReplyPolicy(
    that: this,
    postId: postId,
    policy: policy,
  );

  /// The card "Share my Universe" shares (ADR 0039), naming only the
  /// people in `named`, whom the owner ticked, and only if it draws them.
  Future<ShareCard> shareCard({required List<String> named}) =>
      RustLib.instance.api.crateApiOspOspAppShareCard(that: this, named: named);

  /// One post, or the post a reshare shares, as the node has it.
  Future<Post> showPost({required String id}) =>
      RustLib.instance.api.crateApiOspOspAppShowPost(that: this, id: id);

  Future<NodeStatus> status() =>
      RustLib.instance.api.crateApiOspOspAppStatus(that: this);

  /// Asks the node to sync everyone it follows now. Returns how many new
  /// objects arrived.
  Future<int> sync_() => RustLib.instance.api.crateApiOspOspAppSync(that: this);

  /// One page of a post's replies, after `after` (0 for the first). For the
  /// owner's own posts, all of them, hidden ones too, and the policy.
  /// Anyone else's are read from their node without saying who reads.
  Future<Thread> thread({
    required String postId,
    required PlatformInt64 after,
  }) => RustLib.instance.api.crateApiOspOspAppThread(
    that: this,
    postId: postId,
    after: after,
  );

  /// Trusts someone the node follows, without a request.
  Future<void> trust({required String identity}) => RustLib.instance.api
      .crateApiOspOspAppTrust(that: this, identity: identity);

  /// Requests to be a trusted follower waiting, newest first, and who is
  /// trusted.
  Future<TrustList> trustList() =>
      RustLib.instance.api.crateApiOspOspAppTrustList(that: this);

  /// Undoes a block.
  Future<void> unblock({required String kind, required String id}) => RustLib
      .instance
      .api
      .crateApiOspOspAppUnblock(that: this, kind: kind, id: id);

  /// Stops following someone, whether or not the node has reached theirs.
  Future<void> unfollow({required String identity}) => RustLib.instance.api
      .crateApiOspOspAppUnfollow(that: this, identity: identity);

  /// What the Universe may show (ADR 0033), built on the node from what
  /// it already knows: asking sends nothing to any other node. `region`
  /// is what it opens (ADR 0034 §6): none or empty for the top, `g:<id>`
  /// a group, `p:<identity>` standing at someone, `sky:<l>/<x>/<y>` a
  /// cell of the sky. `lit` lights up where that kind of item is (ADR
  /// 0035 §1); none shows people alone. With `since` the version the app
  /// holds, none means it's unchanged.
  Future<UniverseSnapshot?> universe({
    String? region,
    UniverseLayer? lit,
    String? since,
  }) => RustLib.instance.api.crateApiOspOspAppUniverse(
    that: this,
    region: region,
    lit: lit,
    since: since,
  );

  /// What the node did or saw lately (ADR 0036 §1), oldest first: those
  /// after `since`, the highest `seq` held, or the last day's with none.
  /// Answered by the node alone.
  Future<List<UniverseEvent>> universeEvents({BigInt? since}) => RustLib
      .instance
      .api
      .crateApiOspOspAppUniverseEvents(that: this, since: since);

  /// Stops trusting someone, on every node they were trusted on.
  Future<void> untrust({required String identity}) => RustLib.instance.api
      .crateApiOspOspAppUntrust(that: this, identity: identity);

  /// Waits until the node has the start of a blob, asking it to fetch
  /// the blob if it hasn't, so a player can start on it. The rest
  /// reaches the player as it arrives.
  Future<void> waitForMedia({required String blob}) => RustLib.instance.api
      .crateApiOspOspAppWaitForMedia(that: this, blob: blob);
}
